44		private async getLangModelServer(): Promise<ClaudeLanguageModelServer> {
45			if (!this._langModelServer) {
46				this._langModelServer = this.instantiationService.createInstance(ClaudeLanguageModelServer);
47				await this._langModelServer.start();
48			}
49	
50			return this._langModelServer;
