102		createHandler(): ChatExtendedRequestHandler {
103			return async (request: vscode.ChatRequest, context: vscode.ChatContext, stream: vscode.ChatResponseStream, token: vscode.CancellationToken): Promise<vscode.ChatResult | void> => {
104				const { chatSessionContext } = context;
105				if (!chatSessionContext) {
106					/* Via @claude */
107					// TODO: Think about how this should work
108					stream.markdown(vscode.l10n.t("Start a new Claude Agent session"));
109					stream.button({ command: `workbench.action.chat.openNewSessionEditor.${ClaudeSessionUri.scheme}`, title: vscode.l10n.t("Start Session") });
110					return {};
111				}
112	
113				// Try to handle as a slash command first
114				const slashResult = await this.slashCommandService.tryHandleCommand(request, stream, token);
115				if (slashResult.handled) {
116					return slashResult.result ?? {};
117				}
118	
119				const effectiveSessionId = ClaudeSessionUri.getSessionId(chatSessionContext.chatSessionItem.resource);
120				const yieldRequested = () => context.yieldRequested;
121	
122				// Determine whether this is a new session by checking if a session
123				// already exists on disk via the session service.
124				const sessionUri = ClaudeSessionUri.forSessionId(effectiveSessionId);
125				const existingSession = await this.sessionService.getSession(sessionUri, token);
126				const isNewSession = !existingSession;
127	
128				const modelId = parseClaudeModelId(request.model.id);
129				const selectedPermissionId = chatSessionContext.inputState.groups.find(group => group.id === PERMISSION_MODE_OPTION_ID)?.selected?.id;
130				if (!selectedPermissionId || !isPermissionMode(selectedPermissionId)) {
131					throw new Error(`Permission mode not set for session ${effectiveSessionId}`);
132				}
133				const permissionMode = selectedPermissionId;
134				const selectedFolderUri = getSelectedFolderUri(chatSessionContext.inputState);
135				const folderInfo = await this._controller.getFolderInfoForSession(effectiveSessionId, selectedFolderUri);
136	
137				// Commit UI state to session state service before invoking agent manager
138				this.sessionStateService.setModelIdForSession(effectiveSessionId, modelId);
139				this.sessionStateService.setPermissionModeForSession(effectiveSessionId, permissionMode);
140				this.sessionStateService.setFolderInfoForSession(effectiveSessionId, folderInfo);
141	
142				const rawReasoningEffort = request.modelConfiguration?.[CLAUDE_REASONING_EFFORT_PROPERTY];
143				const reasoningEffort = await this.claudeModels.resolveReasoningEffort(modelId, rawReasoningEffort);
144				this.sessionStateService.setReasoningEffortForSession(effectiveSessionId, reasoningEffort);
145	
146				// Set usage handler to report token usage for context window widget
147				this.sessionStateService.setUsageHandlerForSession(effectiveSessionId, (usage) => {
148					stream.usage(usage);
149				});
150	
151				const prompt = request.prompt;
152				await this._controller.updateItemStatus(effectiveSessionId, vscode.ChatSessionStatus.InProgress, prompt);
153				const result = await this.claudeAgentManager.handleRequest(effectiveSessionId, request, context, stream, token, isNewSession, yieldRequested);
154				await this._controller.updateItemStatus(effectiveSessionId, vscode.ChatSessionStatus.Completed, prompt);
155	
156				// Clear usage handler after request completes
157				this.sessionStateService.setUsageHandlerForSession(effectiveSessionId, undefined);
158	
159				return result.errorDetails ? { errorDetails: result.errorDetails } : {};
160			};
161		}
