165		async provideChatSessionContent(sessionResource: vscode.Uri, token: vscode.CancellationToken, context?: { readonly inputState: vscode.ChatSessionInputState }): Promise<vscode.ChatSession> {
166			const existingSession = await this.sessionService.getSession(sessionResource, token);
167			const history = existingSession ?
168				buildChatHistory(existingSession) :
169				[];
170	
171			const options: Record<string, string | vscode.ChatSessionProviderOptionItem> = {};
172			const groups = context?.inputState.groups ?? [];
173			for (const group of groups) {
174				if (group.selected) {
175					// Only lock the folder group — permission mode must stay editable
176					const locked = group.id === FOLDER_OPTION_ID;
177					options[group.id] = locked
178						? { ...group.selected, locked: true }
179						: group.selected.id;
180				}
181			}
182	
183			return {
184				title: existingSession?.label,
185				history,
186				activeResponseCallback: undefined,
187				requestHandler: undefined,
188				options,
189			};

